-- DEVELOPMENT ONLY: representative inventory, rates, specifications and service coverage.
-- Uses independent demo location/owner records. Never overwrites non-demo inventory.
begin;
insert into public.service_areas(id,name,slug,active,is_demo,postcode_areas) values
('10000000-0000-4000-8000-000000000006','Glasgow','glasgow-catalogue-demo',true,true,array['G','ML','PA']) on conflict do nothing;
insert into public.locations(id,service_area_id,name,reference,postcode,active,collection_available,is_demo) values
('10000000-0000-4000-8000-000000000005','10000000-0000-4000-8000-000000000006','Catalogue demo depot — not a real collection address','DEMO-CATALOGUE','G1 1AA',true,true,true) on conflict do nothing;
insert into public.owners(id,owner_type,company_name,contact_name,email,active,commission_bps,is_demo,notes) values
('10000000-0000-4000-8000-000000000004','company','Catalogue demo owner','Demo contact','demo@example.invalid',true,1500,true,'Internal development fixture. Never publish.') on conflict do nothing;
do $$ declare r record; equipment_uuid uuid; cat uuid;
begin
 for r in select * from (values
 ('jcb-3cx-backhoe-loader','JCB 3CX Backhoe Loader','plant-machinery',19500,97500,50000,true,false,'A versatile backhoe loader for digging, loading and demanding site preparation. Plan access, ground conditions and transport before your hire.', '[{"key":"weight","label":"Operating weight","value":"8,100","unit":"kg"},{"key":"depth","label":"Digging depth","value":5.97,"unit":"m"},{"key":"fuel","label":"Fuel type","value":"Diesel"},{"key":"transmission","label":"Transmission","value":"Powershift"}]'),
 ('1-5t-mini-excavator','1.5T Mini Excavator','plant-machinery',11500,57500,35000,true,false,'Compact digging power for landscaping, foundations and restricted-access jobs. A practical choice when space is tight and precision matters.', '[{"key":"weight","label":"Operating weight","value":"1,500","unit":"kg"},{"key":"width","label":"Minimum width","value":0.99,"unit":"m"},{"key":"fuel","label":"Fuel type","value":"Diesel"}]'),
 ('3t-mini-excavator','3T Mini Excavator','plant-machinery',15000,75000,50000,true,true,'More reach and digging capability for groundwork, drainage and landscaping projects. Check machine width and ground access against your site requirements.', '[{"key":"weight","label":"Operating weight","value":"3,000","unit":"kg"},{"key":"depth","label":"Digging depth","value":2.8,"unit":"m"},{"key":"fuel","label":"Fuel type","value":"Diesel"}]'),
 ('diesel-plate-compactor','Diesel Plate Compactor','landscaping',4500,18000,15000,false,false,'Prepare a firm, even base for paths, paving and groundwork. A robust compactor for suitable granular materials and professional site use.', '[{"key":"weight","label":"Operating weight","value":125,"unit":"kg"},{"key":"width","label":"Plate width","value":500,"unit":"mm"},{"key":"fuel","label":"Fuel type","value":"Diesel"}]'),
 ('industrial-pressure-washer','Industrial Pressure Washer','cleaning',3500,14000,10000,false,false,'Refresh hard surfaces, plant and outdoor work areas with a powerful pressure washer. Confirm water supply and surface suitability before use.', '[{"key":"pressure","label":"Maximum pressure","value":150,"unit":"bar"},{"key":"power","label":"Power source","value":"Electric"},{"key":"supply","label":"Water supply","value":"Mains hose required"}]'),
 ('petrol-generator','Petrol Generator','site-equipment',4200,16800,15000,false,true,'Portable power for suitable tools and temporary site setups. Confirm your load requirements and use outdoors in a well-ventilated location.', '[{"key":"output","label":"Rated output","value":3,"unit":"kVA"},{"key":"fuel","label":"Fuel type","value":"Petrol"},{"key":"voltage","label":"Output voltage","value":"110 / 230","unit":"V"}]'),
 ('concrete-mixer','Concrete Mixer','site-equipment',2800,11200,10000,false,false,'A portable mixer for small building projects and repair work. Mix manageable batches consistently with a stable working setup.', '[{"key":"capacity","label":"Drum volume","value":130,"unit":"L"},{"key":"power","label":"Power source","value":"Electric"},{"key":"voltage","label":"Supply voltage","value":230,"unit":"V"}]'),
 ('scaffold-tower','Scaffold Tower','access-equipment',6000,24000,25000,true,true,'A mobile access tower for appropriate level-ground tasks. Correct assembly, ground assessment and trained use are essential before work begins.', '[{"key":"height","label":"Working height","value":8.2,"unit":"m"},{"key":"capacity","label":"Platform capacity","value":230,"unit":"kg"},{"key":"material","label":"Material","value":"Aluminium"}]'),
 ('floor-sander','Floor Sander','power-tools',4800,19200,15000,false,false,'Prepare suitable wooden floors for a fresh finish. A practical sanding machine for refurbishment, with abrasives selected for the surface and task.', '[{"key":"width","label":"Sanding width","value":200,"unit":"mm"},{"key":"power","label":"Power source","value":"Electric"},{"key":"consumables","label":"Abrasives","value":"Supplied separately"}]'),
 ('sds-rotary-hammer','SDS Rotary Hammer','power-tools',2200,8800,7500,false,false,'Drill and lightly chisel suitable masonry and concrete with an SDS rotary hammer. Select the correct bit and use appropriate dust control.', '[{"key":"chuck","label":"Chuck type","value":"SDS-plus"},{"key":"modes","label":"Modes","value":"Drill / hammer / chisel"},{"key":"power","label":"Power source","value":"Electric"}]'),
 ('stihl-cut-off-saw','Stihl Cut-Off Saw','power-tools',4500,18000,15000,true,false,'A petrol cut-off saw for suitable site cutting tasks. Choose an approved disc and plan dust suppression, protective equipment and safe handling.', '[{"key":"blade","label":"Disc diameter","value":350,"unit":"mm"},{"key":"fuel","label":"Fuel type","value":"Petrol"},{"key":"depth","label":"Maximum cutting depth","value":125,"unit":"mm"}]'),
 ('commercial-carpet-cleaner','Commercial Carpet Cleaner','cleaning',2800,11200,10000,false,false,'Deep-clean suitable carpets and upholstery using spray extraction. Test fabric compatibility first and allow sufficient drying time after cleaning.', '[{"key":"tank","label":"Clean water tank","value":10,"unit":"L"},{"key":"power","label":"Power source","value":"Electric"},{"key":"use","label":"Suitable for","value":"Carpets and upholstery"}]')
 ) as inventory(slug,title,category,daily,weekly,deposit,verify,third_party,description,specs) loop
  -- Correct only this seed's disposable legacy IDs; restrictive booking/block FKs
  -- abort the transaction if an asset already has rental history.
  equipment_uuid:=overlay(overlay(md5('phase3-demo-'||r.slug) placing '4' from 13) placing '8' from 17)::uuid;
  delete from public.equipment where id=md5('phase3-demo-'||r.slug)::uuid and id<>equipment_uuid and is_demo and slug=r.slug;
  select id into strict cat from public.categories where slug=r.category;
  insert into public.equipment(id,title,slug,category_id,description,daily_rate,weekly_rate,security_deposit,verification_required,delivery_eligible,collection_eligible,ownership_type,owner_id,operational_status,base_location_id,listed,is_demo,customer_details)
  values(equipment_uuid,r.title,r.slug,cat,r.description,r.daily,r.weekly,r.deposit,r.verify,true,true,case when r.third_party then 'THIRD_PARTY' else 'COMPANY' end,case when r.third_party then '10000000-0000-4000-8000-000000000004'::uuid else null end,'AVAILABLE','10000000-0000-4000-8000-000000000005',true,true,
   jsonb_build_object('included',jsonb_build_array('Standard machine configuration','Handover and operating guidance'),'requirements',jsonb_build_array('Suitable site access and working area','Appropriate PPE and competent operation'),'operator','Confirm equipment-specific training and any site licensing requirements with the rental team.','cancellation','Demo catalogue: business-specific cancellation and rental terms must be agreed before real bookings open.')) on conflict do nothing;
  if exists(select 1 from public.equipment where id=equipment_uuid and is_demo) then
   insert into public.equipment_images(equipment_id,storage_path,alt_text,is_primary) values(equipment_uuid,'catalogue/demo-phase3/'||r.slug||'.webp','Representative demo illustration of '||r.title,true) on conflict do nothing;
   insert into public.equipment_specifications(equipment_id,key,label,value,unit,display_order)
   select equipment_uuid,x->>'key',x->>'label',x->'value',x->>'unit',ord::integer from jsonb_array_elements(r.specs::jsonb) with ordinality a(x,ord) on conflict do nothing;
  end if;
 end loop;
end $$;
commit;
